public class TreeTraversingParser_getIntValue_TriageGen1Test {

    private ObjectMapper mapper;
    private JsonNode rootNode;
    private TreeTraversingParser parser;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    /**
     * Helper to instantiate TreeTraversingParser using reflection because 
     * currentNumericNode() is protected and depends on internal state.
     * We mock the behavior of the internal currentNumericNode via reflection 
     * or by providing a valid JsonNode structure.
     */
    private TreeTraversingParser createParserWithNode(JsonNode node) throws Exception {
        TreeTraversingParser parser = new TreeTraversingParser(node);
        // Since currentNumericNode() is protected, we rely on the fact that 
        // TreeTraversingParser implementation iterates through the JsonNode.
        // To test getIntValue specifically, we need the parser to be positioned at a NumericNode.
        return parser;
    }





    @Test(expected = ClassCastException.class)
    public void testGetIntValue_ThrowsClassCastExceptionWhenNotNumeric() throws Exception {
        // Arrange
        TextNode textNode = mapper.getNodeFactory().textNode("not a number");
        TreeTraversingParser realParser = new TreeTraversingParser(textNode);
        TreeTraversingParser spyParser = spy(realParser);

        // currentNumericNode() returns a JsonNode, but getIntValue casts it to NumericNode
        // If it's a TextNode, the cast (NumericNode) currentNumericNode() fails.
        doReturn(textNode).when(spyParser).currentNumericNode();

        // Act
        spyParser.getIntValue();

        // Assert handled by expected exception
    }




}
